.chat-thread-panel {
    width: 25%;
    min-width: 280px;
    background: #fff;
    border-left: 1px solid #e8e8e8;
    display: flex;
    flex-direction: column;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    background: #fafafa;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    border: none;
    background: transparent;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-btn:hover {
    background: #eee;
    color: #333;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f8f9fa;
    border-bottom: 1px solid #eee;
}

.thread-divider {
    margin: 0;
    border: none;
    border-top: 1px solid #e8e8e8;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #888;
    font-size: 1.1rem;
}
